function sendQuote(e){e.preventDefault();const g=id=>document.getElementById(id).value;
 const body=`Name: ${g('n')}\nPhone: ${g('ph')}\nEmail: ${g('em')}\nTown: ${g('tw')}\nBuilding: ${g('st')}\n\n${g('msg')}`;
 location.href='mailto:caleb@ibyfax.com?subject='+encodeURIComponent('Quote request – Classic Shed Builders website')+'&body='+encodeURIComponent(body);setTimeout(()=>{location.href='/thank-you/';},400);return false;}


