function rcard(r,hide){
 const a=hide?' aria-hidden="true"':'';
 if(r.promise) return `<div class="mcard"${a}><div class="rhead"><div class="av logo">C</div><div><div class="rname">Classic Shed Builders</div><div class="rsub">Our promise</div></div></div><p class="quote">"${r.text}"</p><div class="rfoot">The Classic promise</div></div>`;
 const foot=r.source==='google'?`<div class="rfoot">Posted on</div><div class="rfoot">${G}<b>Google</b></div>`:r.source==='facebook'?`<div class="rfoot">Posted on</div><div class="rfoot">${FBL}<b style="color:#1877F2">Facebook</b></div>`:`<div class="rfoot">Customer testimonial</div>`;
 const badge=r.source==='google'?CHECK:'';
 const sub=r.source==='facebook'?`<span class="rec">${REC} Recommends</span>`:`<span class="st">${STAR.repeat(r.stars||5)}</span>${r.when||r.meta||''}`;
 return `<div class="mcard"${a}><div class="rhead"><div class="av">${r.name.split(' ').map(w=>w[0]).join('').slice(0,2)}</div><div><div class="rname">${r.name} ${badge}</div><div class="rsub">${sub}</div></div></div><p class="quote">${r.text}</p>${foot}</div>`;
}
document.querySelectorAll('[data-reviews]').forEach(t=>{const real=REVIEWS.filter(r=>!r.promise);
 if(real.length>=3){t.innerHTML=real.map(r=>rcard(r,false)).join('')+real.map(r=>rcard(r,true)).join('');}
 else{t.innerHTML=real.map(r=>rcard(r,false)).join('');t.classList.add('static');t.parentElement.classList.add('static');}});


/* ===== "Ask about this building" buttons prefill the quote form ===== */
document.addEventListener('click',e=>{const a=e.target.closest('[data-ask]');if(a){a.href='/contact/?building='+encodeURIComponent(a.dataset.ask);}
 const d=e.target.closest('[data-design]');if(d){d.href='/design/?model='+encodeURIComponent(d.dataset.design);}});
(()=>{const q=new URLSearchParams(location.search);const f=document.getElementById('st');if(f&&q.get('building'))f.value=q.get('building');})();

/* ===== Design & price: live cash price and rent-to-own from the price list ===== */
const money=v=>'$'+v.toLocaleString('en-US',{minimumFractionDigits:v%1?2:0,maximumFractionDigits:2});
function builder(root){
 root.innerHTML='<div class="bld"><div class="controls"><label>Building line</label><select data-c></select><label>Style</label><select data-m></select><label>Size</label><select data-s></select>'
 +'<p class="note" style="margin-top:12px">Cash price from our current price list, before options and sales tax. Not responsible for typographic price errors; subject to price corrections.</p></div>'
 +'<div class="out"><img alt=""><div class="body"><div class="kicker" data-k></div><div class="big" data-p></div><div data-r style="color:#B3261E;font-weight:600"></div><div class="terms" data-t></div>'
 +'<div style="display:flex;gap:10px;flex-wrap:wrap"><a class="btn" href="#contact" data-ask="">Request a quote on this building</a><a class="btn ghost" data-v href="#">Details</a></div></div></div></div>';
 const C=root.querySelector('[data-c]'),M=root.querySelector('[data-m]'),S=root.querySelector('[data-s]');
 BDATA.forEach((c,i)=>C.add(new Option(c.cat,i)));
 function fillM(){M.innerHTML='';BDATA[C.value].models.forEach((m,i)=>M.add(new Option(m.name,i)));fillS();}
 function fillS(){S.innerHTML='';const m=BDATA[C.value].models[M.value];m.rows.forEach((r,i)=>S.add(new Option(r[0].replace(/ /g,''),i)));show();}
 function show(){const m=BDATA[C.value].models[M.value],r=m.rows[S.value];const img=root.querySelector('.out img');if(MIMG[m.slug]){img.src=MIMG[m.slug];img.alt=m.name;}
  root.querySelector('[data-k]').textContent=BDATA[C.value].cat;
  root.querySelector('[data-p]').textContent=r[0].replace(/ /g,'')+' '+m.name+' · '+money(r[1]);
  root.querySelector('[data-r]').textContent=r[2]?('or '+money(r[2])+'/mo rent-to-own (60 months)'):'Built on site · call for financing terms';
  root.querySelector('[data-t]').innerHTML=(r[2]&&BDATA[C.value].terms)?[[60,27],[48,24],[36,21.6],[24,16.9]].map(([n,d])=>'<div><b>'+money(Math.round(r[1]/d*100)/100)+'</b>'+n+' mo</div>').join(''):'';
  root.querySelector('[data-ask]').dataset.ask=r[0].replace(/ /g,'')+' '+m.name+' ('+money(r[1])+')';
  root.querySelector('[data-v]').href='/models/'+m.slug+'/';}
 C.onchange=fillM;M.onchange=fillS;S.onchange=show;
 root.__select=slug=>{BDATA.forEach((c,ci)=>c.models.forEach((m,mi)=>{if(m.slug===slug){C.value=ci;fillM();M.value=mi;fillS();}}));};
 C.value=0;fillM();M.value=4;fillS();S.value=Math.min(7,S.options.length-1);root.querySelector('[data-t]').style.display='';show();
}
document.querySelectorAll('[data-builder]').forEach(builder);
(()=>{const m=new URLSearchParams(location.search).get('model');if(m)document.querySelectorAll('[data-builder]').forEach(b=>b.__select&&b.__select(m));})();

/* ===== Reviews page: full grid, tied to the building bought when known ===== */
document.querySelectorAll('[data-reviews-grid]').forEach(g=>{g.innerHTML=REVIEWS.filter(r=>!r.promise).map(r=>{let h=rcard(r,false);if(r.building)h=h.replace('</p>','</p><div class="rbuilt">Bought: '+r.building+'</div>');return h;}).join('');});

/* Links pending: replace "#facebook-link-pending" and "#google-review-link-pending" with the real URLs to show these buttons */
document.querySelectorAll('a[href*="-link-pending"]').forEach(a=>{const row=a.closest('.row');(row||a).style.display='none';});

